import pandas as pd
import numpy as np
import plotly.graph_objects as go
from plotly.subplots import make_subplots
import json
import os

# 1. Load Data
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'], utc=True)
df = df.sort_values('Date').reset_index(drop=True)

# 2. Calculate Overall KPIs
start_price = df['Close'].iloc[0]
end_price = df['Close'].iloc[-1]
years = (df['Date'].iloc[-1] - df['Date'].iloc[0]).days / 365.25

cumulative_return = (end_price / start_price) - 1
cagr = (end_price / start_price) ** (1 / years) - 1

df['Daily_Return'] = df['Close'].pct_change()
annualized_volatility = df['Daily_Return'].std() * np.sqrt(252)

df['Cumulative_Max'] = df['Close'].cummax()
df['Drawdown'] = (df['Close'] - df['Cumulative_Max']) / df['Cumulative_Max']
max_drawdown = df['Drawdown'].min()

total_dividends = df['Dividends'].sum()

# 3. Create Visualizations
# Chart 1: Long-Term Price Trend
fig_price = go.Figure()
fig_price.add_trace(go.Scatter(x=df['Date'], y=df['Close'], mode='lines', name='Close Price', line=dict(color='#006fcf')))
fig_price.update_layout(title='AXP Long-Term Price Trend (1972-2026)', xaxis_title='Date', yaxis_title='Close Price (USD)', yaxis_type="log", template='plotly_white')
html_price = fig_price.to_html(full_html=False, include_plotlyjs='cdn')

# Chart 2: Drawdown
fig_dd = go.Figure()
fig_dd.add_trace(go.Scatter(x=df['Date'], y=df['Drawdown'], fill='tozeroy', mode='lines', name='Drawdown', line=dict(color='#d93025')))
fig_dd.update_layout(title='Historical Drawdowns', xaxis_title='Date', yaxis_title='Drawdown', yaxis_tickformat='.0%', template='plotly_white')
html_dd = fig_dd.to_html(full_html=False, include_plotlyjs=False)

# Chart 3: Trading Volume
fig_vol = go.Figure()
# Resample volume to monthly for cleaner visualization
df_monthly = df.set_index('Date').resample('M').agg({'Volume': 'sum', 'Dividends': 'sum'})
fig_vol.add_trace(go.Bar(x=df_monthly.index, y=df_monthly['Volume'], name='Monthly Volume', marker_color='#80868b'))
fig_vol.update_layout(title='Monthly Trading Volume', xaxis_title='Date', yaxis_title='Volume', template='plotly_white')
html_vol = fig_vol.to_html(full_html=False, include_plotlyjs=False)

# Chart 4: Dividends
fig_div = go.Figure()
fig_div.add_trace(go.Bar(x=df_monthly.index, y=df_monthly['Dividends'], name='Dividends', marker_color='#0f9d58'))
fig_div.update_layout(title='Dividend Payments Over Time', xaxis_title='Date', yaxis_title='Total Dividends Paid (USD)', template='plotly_white')
html_div = fig_div.to_html(full_html=False, include_plotlyjs=False)

# 4. Decade-by-Decade Analysis
df['Decade'] = (df['Date'].dt.year // 10) * 10
decade_stats = []
for decade, group in df.groupby('Decade'):
    start_p = group['Close'].iloc[0]
    end_p = group['Close'].iloc[-1]
    ret = (end_p / start_p) - 1
    vol = group['Daily_Return'].std() * np.sqrt(252)
    div = group['Dividends'].sum()
    decade_stats.append({
        'Decade': f"{decade}s",
        'Return': f"{ret:.2%}",
        'Volatility': f"{vol:.2%}",
        'Total Dividends': f"${div:.2f}"
    })

decade_html = "<table class='table'><thead><tr><th>Decade</th><th>Return</th><th>Annualized Volatility</th><th>Total Dividends</th></tr></thead><tbody>"
for stat in decade_stats:
    decade_html += f"<tr><td>{stat['Decade']}</td><td>{stat['Return']}</td><td>{stat['Volatility']}</td><td>{stat['Total Dividends']}</td></tr>"
decade_html += "</tbody></table>"


# 5. Generate HTML Report
