            margin-bottom: 40px;
        }}
        .kpi-card {{
            flex: 1;
            min-width: 180px;
            background: #e8f0fe;
            padding: 20px;
            border-radius: 8px;
            text-align: center;
            border-left: 5px solid #1a73e8;
        }}
